frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {  // Only show when submitted
            frm.add_custom_button('Send via WhatsApp', () => {

                frappe.call({
                    method: 'erpnext.accounts.doctype.sales_invoice.sales_invoice.send_invoice_whatsapp',
                    args: {
                      invoice_name: frm.doc.name

                    },
                    callback: function(r) {
                        console.log(r.message_status)
                        frappe.msgprint("Whatsapp Message Sent Successfully")
                    }
                });
            });
        }
    }
});

frappe.ui.form.on('Item Group Rate Master', {
	item_group: function(frm) {
        if (frm.doc.item_group) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Item Group',
                    filters: {
                        name: frm.doc.item_group
                    },
                    fieldname: 'price'
                },
                callback: function(r) {
                    if (r.message) {
                        price_total=frm.doc.price_master + r.message.price
                        frm.set_value('price_master', price_total);
                    }
                }
            });
        }
    }
})

frappe.ui.form.on('Sales Order Item', {
  item_code: function(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (row.item_code ) {
      frappe.call({
        method: "frappe.client.get_value",
        args: {
          doctype: "Bin",
          filters: {
            item_code: row.item_code

          },
          fieldname: "actual_qty"
        },
        callback: function(r) {
            console.log("r.message.actual_qty::"+r.message.actual_qty)
          if (r.message) {
            frappe.model.set_value(cdt, cdn, "available_stock", r.message.actual_qty);
          } else {
            frappe.model.set_value(cdt, cdn, "available_stock", 0);
          }
        }
      });
    }
  },

});

frappe.ui.form.on("Sales Order", {
  refresh: function(frm) {
    if (frm.doc.docstatus === 0) {
      frm.add_custom_button("Select from Available Stock", () => {
        open_stock_ledger_picker(frm);
      });
    }
  }
});

function open_stock_ledger_picker(frm) {
 if (!frm.doc.customer) {
        frappe.msgprint("Please select a Customer before choosing items from stock.");
        return;
    }
  frappe.call({
    method: "erpnext.selling.doctype.sales_order.sales_order.get_individual_stock_entries",
    args: { customer: frm.doc.customer },
    callback: function(r) {
      if (!r.message || r.message.length === 0) {
        frappe.msgprint("No stock available.");
        return;
      }

      const items = r.message;
      const dialog = new frappe.ui.Dialog({
        title: "Select Items from Stock Ledger",
        fields: [
          {
            fieldtype: "Data",
            label: "Search Item",
            fieldname: "search_term",
            onchange: function() {
              const term = dialog.get_value("search_term").toLowerCase();
              render_stock_table(items.filter(i => i.item_name.toLowerCase().includes(term)));
            }
          },
          {
            fieldtype: "HTML",
            fieldname: "stock_table"
          }
        ],
        primary_action_label: "Add Selected",
        primary_action() {
          const selected = Array.from(dialog.fields_dict.stock_table.$wrapper.find("input:checked"))
            .map(input => items[parseInt(input.dataset.index)]);
          selected.forEach(item => {
            frm.add_child("items", {
              item_code: item.item_code,
              item_name : item.item_name,
              qty: item.actual_qty,
              size:item.size,
              mm:item.mm,
            rate: parseFloat(item.item_price || 0).toFixed(2),
            uom: item.stock_uom
            });
          });
          frm.doc.items = frm.doc.items.filter(row => row.item_code);
          frm.refresh_field("items");
          frm.trigger("calculate_taxes_and_totals");
          dialog.hide();
        }
      });

      function render_stock_table(filtered) {
       const html = filtered.map((item, i) => `
  <div style="padding:4px;border-bottom:1px solid #eee;">
    <input type="checkbox" data-index="${i}" />
    <strong>${item.item_code}</strong> — ${item.item_name}  
    <span style="float:right;">${item.actual_qty} ${item.stock_uom} @ ₹${parseFloat(item.item_price).toFixed(2)}</span>
    <br><small>Warehouse: ${item.warehouse}</small>
    ${item.batch_no ? `<br><small>Batch: ${item.batch_no}</small>` : ""}
    ${item.serial_no ? `<br><small>Serial: ${item.serial_no}</small>` : ""}
  </div>
`).join("");

        dialog.fields_dict.stock_table.$wrapper.html(html);
      }

      dialog.show();
      render_stock_table(items);
    }
  });
}

